{
  "technical_and_design_decisions": [
    "Use Go as the primary programming language, consistent with the Hyperledger Fabric codebase.",
    "For U1, modify the `rwset` protobuf definitions to include values in the readset, and update the transaction validation logic (`txvalidator`) to compare these values against the peer's world state during validation.",
    "For U2-U8, create a standalone Go package (e.g., `configlib`) that accepts strongly-typed Go structs and byte slices for cryptographic material, avoiding dependencies on `viper` or `yaml` parsing.",
    "Reuse existing Fabric cryptographic primitives and protobuf definitions where possible, but ensure functions accept key material directly as input parameters rather than relying on MSP configuration files.",
    "Acceptance tests will be implemented using the standard Go testing framework, comparing generated protobuf structures using `proto.Equal`."
  ],
  "assumptions": [
    "The developer has access to the Hyperledger Fabric source code, development environment, and necessary tooling (protoc, etc.).",
    "1 workday equals 8 hours of focused development effort.",
    "The 'fit-for-purpose library' will be integrated into the main Fabric repository or a closely related official repository.",
    "Existing Fabric integration tests and tools (like `configtxgen` and `cryptogen`) can be used as reference implementations to verify semantic equivalence.",
    "No external UI is required; all functions will be exposed as programmatic Go APIs."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement Readset Value Inclusion and Tamper Validation (U1)",
      "activity_description": "Modify the read/write set data structures to include values in the readset. Update the transaction validation logic to compare these values against the peer's world state and invalidate transactions if tampering is detected.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Channel Creation Transaction Library (U2)",
      "activity_description": "Copy and adapt necessary structures from the `genesisconfig` package into a new fit-for-purpose library. Implement `CreateChannelTx` function to generate a proto-encoded genesis block without using viper/yaml or requiring network access.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Detached Signature Generation (U3)",
      "activity_description": "Create a function to sign a `ChannelUpdate` transaction and generate a detached signature, taking the key material directly as an input parameter.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement Signed Channel Config Update Assembly (U4)",
      "activity_description": "Create a function that takes a `ConfigUpdate` transaction and a collection of detached signatures to assemble a complete, signed channel config update transaction.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement max_message_count Channel Update Generator (U5)",
      "activity_description": "Create a fit-for-purpose library function to generate an unsigned channel update transaction that modifies the `max_message_count` batch size parameter.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement Organization ConfigGroup Generator (U6)",
      "activity_description": "Create a fit-for-purpose library function to generate a `ConfigGroup` representing an Organization, accepting necessary cryptographic material directly as input.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement ConfigUpdate Calculator (U7)",
      "activity_description": "Create a fit-for-purpose library function to calculate a `ConfigUpdate` message that updates a base config to a modified config, semantically equivalent to `configtxlator compute_update`.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement Consortium Org Addition Function (U8)",
      "activity_description": "Create a fit-for-purpose function that adds an org definition to a named consortium in the system channel configuration, generating an unsigned channel update transaction.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A9",
      "activity_name": "Unit and Integration Testing",
      "activity_description": "Write and execute unit and integration tests for all new functions and modified validation logic, ensuring semantic equivalence with existing tools and proper handling of edge cases.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation and Code Review",
      "activity_description": "Document the new library APIs, update relevant Fabric documentation, and perform code reviews to ensure compliance with project standards.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 39
  }
}

